const ZD_BLOCK_CATALOG={"ai-engine": {"name": "AI Engine", "status": "Produção"}, "calendar": {"name": "Calendar", "status": "Beta"}, "commerce": {"name": "Commerce", "status": "Beta"}, "data-store": {"name": "Data Store", "status": "Produção"}, "decision-engine": {"name": "Decision Engine", "status": "Produção"}, "iam": {"name": "IAM", "status": "Produção"}, "webhooks-engine": {"name": "Webhooks Engine", "status": "Produção"}, "wpp-business": {"name": "WPP Business", "status": "Produção"}};
/* A data-driven concept preview. All actions below are local demonstrations, not AI inference or live services. */
const ZD_CASES={
 clinic:{name:'Clara',kind:'Cuidado, com menos espera.',audience:'Pessoas que querem marcar uma consulta',record:'Consulta de acompanhamento',person:'Alex Martins',description:'Do primeiro contato ao horário confirmado, uma experiência que aproxima paciente e equipe.',action:'Escolher um horário',options:['Amanhã · 09h','Amanhã · 14h','Sexta · 10h'],choiceLabel:'Horário',review:'Confira sua consulta',finish:'Seu horário ganhou um lugar.',finishSub:'A equipe acompanha o agendamento e pode ajudar no próximo passo.',stages:['Escolher','Conferir','Confirmar'],blocks:[['wpp-business','Conversar no canal do paciente'],['calendar','Consultar a agenda autorizada'],['data-store','Organizar a solicitação'],['ai-engine','Compreender a conversa']],flow:[['A pessoa conta o que precisa','Uma mensagem inicia a jornada.'],['Consultar a agenda','Buscar opções na agenda conectada.'],['A pessoa escolhe','Confirmar preferência e disponibilidade.'],['Registrar e confirmar','A equipe acompanha o agendamento.']],placeholder:'Quero uma clínica em que agendar pelo WhatsApp seja simples.',hypothesis:'Exemplo de agendamento, sem diagnóstico ou orientação clínica.'},
 credit:{name:'Lume',kind:'Uma proposta. Mais clareza.',audience:'Pessoas que buscam uma solução de crédito',record:'Proposta de crédito',person:'Alex Martins',description:'Uma jornada para entender a necessidade, organizar a proposta e acompanhar cada etapa.',action:'Começar a proposta',options:['Meu projeto','Meu negócio','Minha mobilidade'],choiceLabel:'Objetivo',review:'Uma proposta com contexto',finish:'Seu pedido tem um próximo passo.',finishSub:'A proposta segue para avaliação. Esta demonstração não realiza decisão de crédito.',stages:['Descrever','Organizar','Acompanhar'],blocks:[['iam','Delimitar quem pode acessar'],['data-store','Organizar os dados da proposta'],['decision-engine','Aplicar a política configurada'],['wpp-business','Manter a pessoa informada']],flow:[['Entender a necessidade','A pessoa descreve o objetivo.'],['Organizar a proposta','Reunir os dados previstos no produto.'],['Avaliar pela política','Uma regra versionada orienta a análise.'],['Informar o próximo passo','Sem promessa de aprovação automática.']],placeholder:'Quero uma experiência simples para solicitar crédito e acompanhar a proposta.',hypothesis:'Fluxo ilustrativo. Sem consulta real, cálculo, oferta ou concessão de crédito.'},
 hiring:{name:'Encontro',kind:'Talento encontra oportunidade.',audience:'Candidatos e equipes de recrutamento',record:'Conversa de recrutamento',person:'Alex Martins',description:'Uma experiência para conhecer a pessoa, organizar informações e aproximar candidato e recrutador.',action:'Conhecer a oportunidade',options:['Produto e design','Tecnologia','Operações'],choiceLabel:'Área de interesse',review:'Seu próximo encontro',finish:'Uma conversa pode abrir caminhos.',finishSub:'A equipe recebe o contexto e combina as próximas etapas com a pessoa.',stages:['Conhecer','Apresentar','Conversar'],blocks:[['wpp-business','Conectar candidato e equipe'],['data-store','Organizar informações da conversa'],['calendar','Combinar uma entrevista'],['ai-engine','Resumir o contexto informado']],flow:[['Começar uma conversa','A pessoa indica seu interesse.'],['Organizar o contexto','Resumir somente o que foi informado.'],['Recrutador revisa','Decisões de seleção permanecem humanas.'],['Combinar uma entrevista','Consultar a agenda autorizada.']],placeholder:'Quero conectar candidatos e recrutadores pelo WhatsApp, com entrevistas mais organizadas.',hypothesis:'Sem classificação automática de candidatos ou decisão de contratação.'},
 commerce:{name:'Próxima',kind:'Da escolha à próxima entrega.',audience:'Clientes e equipes de uma loja',record:'Pedido de demonstração',person:'Alex Martins',description:'Catálogo, pedido e conversa conectados para dar clareza à compra e ao atendimento.',action:'Explorar o catálogo',options:['Essencial','Dia a dia','Novidades'],choiceLabel:'Coleção',review:'Uma escolha, bem acompanhada',finish:'O pedido encontrou seu caminho.',finishSub:'A equipe acompanha a solicitação. Nenhuma compra ou cobrança foi realizada.',stages:['Explorar','Escolher','Acompanhar'],blocks:[['commerce','Organizar catálogo e pedido'],['wpp-business','Aproximar compra e conversa'],['data-store','Guardar preferências do produto'],['webhooks-engine','Comunicar os sistemas conectados']],flow:[['Explorar as opções','O cliente começa pelo que procura.'],['Organizar a escolha','Consultar catálogo e disponibilidade.'],['Confirmar a intenção','A pessoa revisa antes de continuar.'],['Acompanhar o pedido','Eventos alimentam os sistemas conectados.']],placeholder:'Quero conectar a loja ao WhatsApp e acompanhar os pedidos em um só lugar.',hypothesis:'Produtos e estados fictícios. Não há pagamento ou movimentação de estoque.'},
 service:{name:'Conecta',kind:'Cada pedido, com um caminho.',audience:'Clientes e equipes de atendimento',record:'Solicitação de atendimento',person:'Alex Martins',description:'Uma conversa que entende o pedido, reúne o contexto e ajuda a equipe a agir com mais clareza.',action:'Iniciar uma solicitação',options:['Preciso de ajuda','Quero acompanhar','Tenho uma ideia'],choiceLabel:'Motivo',review:'Vamos organizar seu pedido',finish:'Seu pedido está no lugar certo.',finishSub:'Uma pessoa pode continuar a conversa com o contexto já organizado.',stages:['Conversar','Organizar','Resolver'],blocks:[['wpp-business','Unir mensagem e atendimento'],['ai-engine','Organizar o contexto da conversa'],['data-store','Manter as informações do pedido'],['webhooks-engine','Conectar o sistema existente']],flow:[['Receber a intenção','A pessoa explica com suas palavras.'],['Aproximar o contexto','Consultar somente as fontes autorizadas.'],['Preparar o próximo passo','Separar uma sugestão de uma ação real.'],['Continuar com a equipe','Transferir o contexto sem recomeçar.']],placeholder:'Quero conectar meu atendimento aos sistemas que já tenho.',hypothesis:'Exemplo de atendimento. Os dados e as operações são demonstrativos.'}
};
function zdConcept(s){const t=(s.idea+' '+s.context+' '+s.focus).toLowerCase();let key=/cl[ií]nica|m[eé]dic|consulta|paciente|veterin|sa[uú]de/.test(t)?'clinic':/cr[eé]dito|financi|empr[eé]st|banc/.test(t)?'credit':/recrut|candidat|entrevista|vaga/.test(t)?'hiring':/loja|com[eé]rc|commerce|compra|cat[aá]logo|venda/.test(t)?'commerce':'service';return {key,...ZD_CASES[key]};}
function zdJourney(s,d){const nodes=d.flow.slice();if(s.demo.human&&!nodes.some(([x])=>/recrutador|revisa/i.test(x)))nodes.splice(nodes.length-1,0,['Uma pessoa revisa','A etapa exige uma decisão humana antes de seguir.']);return nodes;}
function zdBrief(s){const d=zdConcept(s);return {schemaVersion:'1.0',mode:'mock',identity:{...s.identity},idea:s.idea,context:s.context,goal:s.focus,concept:{name:d.name,sector:d.key,summary:d.description,hypotheses:[d.hypothesis,'Nome, telas e fluxo são propostas ilustrativas, não especificação validada.'],buildingBlocks:d.blocks.map(([slug,purpose])=>({slug,purpose})),journey:zdJourney(s,d).map(([title,description])=>({title,description})),humanReview:s.demo.human,preferredView:s.demo.device,refinements:s.demo.refinements.slice()},contact:{name:s.name,channel:s.channel,address:s.address},handoff:{requested:s.demo.handoffRequested,confirmed:s.demo.consent,state:s.demo.assumed?'simulated_assigned':'not_transmitted'}};}
function zdScreen(s,d){const n=s.demo.screen,choice=s.demo.selection||d.options[0];return `<div class="zd-browser" ${s.demo.device==='phone'?'inert aria-hidden="true"':''}><div class="zd-browser-bar"><span><i></i><i></i><i></i></span><span>${zEsc(d.name.toLowerCase())}.produto / conceito</span><span>↗</span></div><div class="zd-app"><nav class="zd-app-nav" aria-label="Telas do produto conceitual"><strong>${zEsc(d.name)}<b>.</b></strong><span>SEU ESPAÇO</span>${d.stages.map((x,i)=>`<button data-zd-screen="${i}" ${n===i?'aria-current="page"':''}><i>0${i+1}</i>${x}</button>`).join('')}<small>Uma composição<br>com Catalisa.</small></nav><div class="zd-app-content"><div class="zd-app-top"><span>${zEsc(d.record)}</span><span class="zd-avatar">A</span></div>${n===0?`<div class="zd-app-welcome"><span class="zd-mini-label">OLÁ, ALEX</span><h3 tabindex="-1">${zEsc(d.kind)}</h3><p>${zEsc(d.description)}</p></div><div class="zd-app-options">${d.options.map((x,i)=>`<button data-zd-choice="${i}" aria-pressed="${choice===x}"><span class="zd-option-icon">${['◒','◐','◓'][i]}</span><span>${zEsc(x)}</span><i>↗</i></button>`).join('')}</div><button class="zd-app-cta" data-zd-screen="1">${zEsc(d.action)} <span>→</span></button>`:n===1?`<span class="zd-mini-label">UM PASSO DE CADA VEZ</span><h3 tabindex="-1">${zEsc(d.review)}</h3><div class="zd-app-review"><span>${zEsc(d.choiceLabel)}</span><strong>${zEsc(choice)}</strong><span>Quem participa</span><strong>${zEsc(d.person)}</strong><span>Próximo passo</span><strong>${s.demo.human?'Revisão por uma pessoa':d.key==='credit'?'Avaliação da proposta':'Confirmação do pedido'}</strong></div><p class="zd-app-caption">Você confere o contexto antes de continuar.</p><button class="zd-app-cta" data-zd-screen="2">Confirmar nesta demo <span>→</span></button>`:`<div class="zd-app-success"><span class="zd-success-mark">✓</span><span class="zd-mini-label">SIMULAÇÃO / PEDIDO 024</span><h3 tabindex="-1">${zEsc(s.demo.human?"Seu pedido aguarda uma revisão.":d.finish)}</h3><p>${zEsc(s.demo.human?"Uma pessoa confere o contexto antes da confirmação. Nenhuma ação real foi realizada.":d.finishSub)}</p><div class="zd-mini-timeline"><span>Contexto organizado</span><span>${s.demo.human?'Revisão humana prevista':'Próximo passo preparado'}</span><span>Acompanhamento disponível</span></div><button class="zd-app-reset" data-zd-screen="0">Experimentar novamente ↺</button></div>`}</div></div></div><div class="zd-phone" aria-label="Versão móvel do produto conceitual"><div class="zd-phone-island"></div><div class="zd-phone-head"><strong>${zEsc(d.name)}.</strong><span>CONCEITO</span></div><div class="zd-phone-orbit"><span>${n===2?'✓':n===1?'◒':'↗'}</span></div><span class="zd-mini-label">${n===2?'UM PRÓXIMO PASSO':n===1?'FEITO COM CONTEXTO':'PODE COMEÇAR POR AQUI'}</span><h4>${zEsc(n===2?(s.demo.human?'Em revisão.':'Tudo conectado.'):n===1?choice:d.kind)}</h4><p>${zEsc(n===2?(s.demo.human?'Uma pessoa confere antes de continuar.':'Acompanhe sem precisar recomeçar a conversa.'):n===1?'Uma experiência que acompanha cada escolha.':'Uma conversa pode ser o primeiro passo.')}</p><button data-zd-screen="${n===2?0:n+1}" aria-label="${n===2?'Reiniciar demonstração no celular':'Avançar na demonstração do celular'}">${n===2?'Recomeçar':'Continuar'} ↗</button><small>Dados de demonstração</small></div>`;}
function zdBlocks(s,d){return `<div class="zd-blocks-scene"><div class="zd-blocks-origin"><span>SEU PRODUTO</span><h3 tabindex="-1">${zEsc(d.name)}<em>.</em></h3><p>Uma experiência.<br>Responsabilidades conectadas.</p><svg viewBox="0 0 230 180" aria-hidden="true"><circle cx="115" cy="90" r="66" fill="none" stroke="#ccb6dc"/><path d="M49 90H181M115 24V156" stroke="#b698cb" stroke-dasharray="3 6"/><path d="M72 90L115 65L158 90L115 115Z" fill="#9a72b6"/><path d="M72 90V105L115 130V115Z" fill="#80549e"/><path d="M115 115L158 90V105L115 130Z" fill="#674180"/><circle class="zd-block-dot" cx="115" cy="24" r="8" fill="#eeb174"/></svg></div><div class="zd-block-list">${d.blocks.map(([slug,why],i)=>{const b=ZD_BLOCK_CATALOG[slug];return `<div><span class="zd-block-number">0${i+1}</span><div><h4>${zEsc(b?.name||slug)}</h4><p>${zEsc(why)}</p><a href="/capacidades/${slug}/" target="_blank" rel="noopener">Conhecer a peça ↗</a></div><span class="zd-block-stage">${zEsc(b?.status||'Consultar catálogo')}</span></div>`}).join('')}</div></div><div class="zd-hypothesis">Composição sugerida para explorar. Disponibilidade, configuração e escopo de cada peça precisam ser validados para o produto.</div>`;}
function zdFlow(s,d){const nodes=zdJourney(s,d);return `<div class="zd-flow-scene"><div class="zd-flow-heading"><span>UMA JORNADA, DO COMEÇO AO PRÓXIMO PASSO</span><h3 tabindex="-1">As conexões<br>também têm <em>uma ordem.</em></h3><button data-zd="play" class="zd-run">${s.demo.running?'Recomeçar percurso':'Ver o percurso acontecer'} <span>▷</span></button></div><ol class="zd-flow-nodes">${nodes.map(([title,desc],i)=>`<li class="${s.demo.flowIndex===i?'zd-node-active':s.demo.flowIndex>i?'zd-node-done':''}"><button data-zd-node="${i}" aria-pressed="${s.demo.flowIndex===i}"><span>${s.demo.flowIndex>i?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${zEsc(title)}</strong><p>${zEsc(desc)}</p></div><i>${/pessoa|recrutador/i.test(title)?'◉':'↘'}</i></button></li>`).join('')}</ol></div><div class="zd-hypothesis">Jornada conceitual. A animação não executa consultas, decisões ou operações reais.</div>`;}
function zdView(s){const d=zdConcept(s);return `<div class="zd-workspace"><div class="zd-reveal-header"><div><span class="z-kicker">DA CONVERSA A UMA PRIMEIRA FORMA</span><h1 id="z-title" tabindex="-1">Sua ideia,<br><em>em movimento.</em></h1><p>Um conceito para explorar, ajustar e conversar.<br>Experimente as telas. Descubra o que conecta tudo.</p></div><div class="zd-concept-stamp"><span>CONCEITO / ${zEsc(d.name.toUpperCase())}</span><strong>Uma possibilidade.<br>O começo de muitas.</strong><small>Prévia demonstrativa · sem IA conectada</small></div></div><div class="zd-layout"><section class="zd-exhibit" aria-label="Demonstração conceitual do produto"><div class="zd-exhibit-top"><div role="tablist" aria-label="Explore seu conceito">${[['product','O produto'],['blocks','As peças'],['flow','A jornada']].map(([key,label])=>`<button id="zd-tab-${key}" role="tab" data-zd-tab="${key}" aria-selected="${s.demo.tab===key}" aria-controls="zd-panel" tabindex="${s.demo.tab===key?'0':'-1'}">${label}</button>`).join('')}</div><span class="zd-concept-badge">${s.demo.human?'COM REVISÃO HUMANA':'PRIMEIRA COMPOSIÇÃO'}</span></div><div id="zd-panel" role="tabpanel" aria-labelledby="zd-tab-${s.demo.tab}" class="zd-panel zd-panel-${s.demo.tab}">${s.demo.tab==='product'?`<div class="zd-device-toolbar"><span>TELAS CLICÁVEIS / DADOS FICTÍCIOS</span><div><button data-zd-device="both" aria-pressed="${s.demo.device==='both'}">Desktop + app</button><button data-zd-device="phone" aria-pressed="${s.demo.device==='phone'}">Só aplicativo</button></div></div><div class="zd-product-scene ${s.demo.device==='phone'?'zd-device-phone':''}">${zdScreen(s,d)}</div><div class="zd-screen-steps">${d.stages.map((x,i)=>`<button data-zd-screen="${i}" aria-pressed="${s.demo.screen===i}"><span>0${i+1}</span>${x}<i>${i<2?'→':'↗'}</i></button>`).join('')}</div>`:s.demo.tab==='blocks'?zdBlocks(s,d):zdFlow(s,d)}</div></section><aside class="zd-guide"><div class="zd-guide-top"><span class="zd-guide-mark">c.</span><div>Catalisa<small>Conversa com ${zEsc(s.name)} · simulada</small></div><span class="zd-guide-dot"></span></div><p class="zd-guide-message" role="status">${zEsc(s.demo.reply||`Trouxemos sua ideia para um exemplo de ${d.key==='clinic'?'agendamento':d.key==='credit'?'jornada de crédito':d.key==='hiring'?'recrutamento':d.key==='commerce'?'compra e atendimento':'atendimento conectado'}. O nome e os detalhes são hipóteses. Você pode explorar e ajustar antes de falar com a equipe.`)}</p><div class="zd-adjustments"><span>EXPERIMENTE UM AJUSTE</span><button data-zd="human">${s.demo.human?'Remover revisão adicional':'Incluir revisão humana'} <i>↗</i></button><button data-zd="app">Ver como aplicativo <i>↗</i></button><button data-zd="explain">Me explique as peças <i>↗</i></button></div><form id="zd-refine-form"><label for="zd-refine">Continue a conversa</label><div><textarea id="zd-refine" rows="2" maxlength="500" placeholder="Quero uma pessoa revisando antes de confirmar…">${zEsc(s.demo.draft||'')}</textarea><button type="submit" aria-label="Pedir ajuste no conceito">↗</button></div><small>Texto livre. Nesta demo, experimente revisão humana, aplicativo ou explicação das peças.</small><p id="zd-refine-status" role="status"></p></form><details class="zd-context"><summary>O que trouxe você até aqui <span>+</span></summary><p>${zEsc(s.idea)}</p><p>${zEsc(s.context)}</p><p>${zEsc(s.focus)}</p><button data-zd="review">Ajustar o ponto de partida ↗</button></details><button data-zd="handoff" class="z-primary zd-handoff-cta">Conversar com uma pessoa <span>↗</span></button><span class="zd-handoff-note">Na versão conectada, sua conversa e esta prévia seguem juntas para a equipe.</span></aside></div><div class="zd-bottom"><p><strong>Uma hipótese para conversar.</strong> ${zEsc(d.hypothesis)} Nome e interface são fictícios.</p><div><button data-z="download">Levar o conceito ↓</button><button data-zd="sample">Explorar outro exemplo ↗</button><button data-z="restart">Recomeçar ↺</button></div></div><p class="z-copy-status" role="status"></p></div>`;}
function zdHandoff(s){const d=zdConcept(s),b=zdBrief(s);return `<div class="zd-handoff"><span class="z-kicker">A CONVERSA SEGUE COM O QUE JÁ FOI CONSTRUÍDO</span><h1 id="z-title" tabindex="-1">Sem recomeçar.<br><em>Com contexto.</em></h1><p class="z-lead">Você, o agente e a equipe podem continuar<br>a partir da mesma primeira ideia.</p><div class="zd-transfer-layout"><section class="zd-transfer-client"><div class="zd-transfer-symbol">${s.demo.assumed?'↗':'◒'}</div><span class="zd-mini-label">${s.demo.assumed?'EQUIPE / DEMONSTRAÇÃO':'CONTINUIDADE / DEMONSTRAÇÃO'}</span><h2>${s.demo.assumed?'Agora, a conversa é com uma pessoa.':'O próximo passo está preparado.'}</h2><p>${s.demo.assumed?`“${zEsc(s.name)}, já tenho ${s.demo.generated?"sua ideia, o conceito "+zEsc(d.name)+" e os ajustes que você pediu":"o contexto da nossa conversa"}. Podemos começar pelo que você quer aprofundar.”`:'Na versão conectada, uma pessoa receberá o histórico'+(s.demo.generated?' e a prévia do produto':' da conversa')+'. Você não precisará explicar tudo de novo.'}</p><div class="zd-transfer-status"><span></span>${s.demo.assumed?'Atendimento humano simulado':'Contexto reunido · nada transmitido'}</div>${!s.demo.assumed?'<button class="z-primary" data-zd="assume">Simular a equipe assumindo <span>↗</span></button>':'<button class="z-primary" data-zd="return-demo">Voltar ao nosso conceito <span>↗</span></button>'}<small>Protótipo local. Não há fila, atendente ou canal conectado. Nenhuma mensagem foi enviada.</small></section><section class="zd-team-packet"><div class="zd-packet-top"><span>COMO CHEGARIA AO ATENDIMENTO</span><span>PRÉVIA DO CONTEXTO</span></div><div class="zd-packet-person"><span class="zd-avatar">${zEsc(s.name.charAt(0).toUpperCase())}</span><div><strong>${zEsc(s.name)}</strong><small>${s.channel==='here'?'Continuar na página':s.channel==='email'?'E-mail: '+zEsc(s.address):s.channel==='whatsapp'?'WhatsApp: '+zEsc(s.address):'Sem canal de retorno informado'}</small></div></div><dl><dt>O que quer construir</dt><dd>${zEsc(s.idea)}</dd><dt>Contexto e direção</dt><dd>${zEsc(s.context)}<br>${zEsc(s.focus)}</dd><dt>Conceito para explorar</dt><dd>${s.demo.generated?zEsc(d.name)+" / "+zEsc(d.kind):"Conversa aberta. Nenhum conceito foi gerado."}</dd><dt>O que acompanha a conversa</dt><dd>Histórico${s.demo.generated?` · 3 telas conceituais · ${d.blocks.length} Building Blocks sugeridos · jornada`:" · conversa aberta, sem conceito gerado"}${s.demo.human?' · revisão humana':''}${s.demo.refinements.length?' · ajustes solicitados':''}</dd><dt>Estado do encaminhamento</dt><dd>Simulação local, sem transmissão.</dd></dl><button data-zd="return-demo">Reabrir a prévia do produto ↗</button></section></div><div class="zd-bottom"><p>A pessoa recebe uma primeira direção, com as hipóteses abertas para validação.</p><div><button data-z="download">Levar conversa e conceito ↓</button><button data-z="restart">Começar outra conversa ↺</button></div></div><p class="z-copy-status" role="status"></p></div>`;}
